mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, update_time = #{updateTime}, update_user = #{updateUser}, status = #{status},
where id = #{id}

mapper.select:
select d.id as dish_id, d.name, d.category_id, d.price, p.spicy_level, p.sweetness_level, p.oiliness_level, cast(p.tags as char) as tags_json, cast(p.allergens as char) as allergens_json, (select df.value from dish_flavor df where df.dish_id = d.id and df.name = '辣度' order by df.id asc limit 1) as flavor_options_json from dish d inner join dish_profile p on p.dish_id = d.id where d.status = 1
and d.price >= #{minPrice}
and d.price <= #{maxPrice}
and d.category_id = #{categoryId}
order by d.id asc limit 500
